import { Annotation, StateGraph, START, END } from "@langchain/langgraph";

const State = Annotation.Root({ question: Annotation(), answer: Annotation() });
const app = new StateGraph(State)
  .addNode("respond", (s) => ({ answer: "You asked: " + s.question }))
  .addEdge(START, "respond")
  .addEdge("respond", END)
  .compile();
console.log(await app.invoke({ question: "What is RAG?" }));
